-- Forward-only Argentina launch baseline. Historical migrations are inventory
-- input only; this file is the sole selected additive shape for this slice.
CREATE TABLE IF NOT EXISTS "_prisma_migrations" (
  "id" TEXT NOT NULL,
  "checksum" TEXT NOT NULL,
  "finished_at" TIMESTAMP(3),
  "migration_name" TEXT NOT NULL,
  "logs" TEXT,
  "rolled_back_at" TIMESTAMP(3),
  "started_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "applied_steps_count" INTEGER NOT NULL DEFAULT 0,
  CONSTRAINT "_prisma_migrations_pkey" PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "TusTenant" ("id" TEXT NOT NULL, "slug" TEXT NOT NULL, "name" TEXT NOT NULL, "status" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "TusTenant_pkey" PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "User" ("id" TEXT NOT NULL, "email" TEXT NOT NULL, "normalizedEmail" TEXT NOT NULL, "displayName" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "User_pkey" PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "Account" ("id" TEXT NOT NULL, "userId" TEXT NOT NULL, "tenantId" TEXT NOT NULL, "roles" TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[], "status" TEXT NOT NULL, "emailVerifiedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Account_pkey" PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "Session" ("id" TEXT NOT NULL, "accountId" TEXT NOT NULL, "tenantId" TEXT NOT NULL, "deviceId" TEXT NOT NULL, "accessTokenDigest" TEXT NOT NULL, "roles" TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[], "permissions" TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[], "createdAt" TIMESTAMP(3) NOT NULL, "expiresAt" TIMESTAMP(3) NOT NULL, "revokedAt" TIMESTAMP(3), CONSTRAINT "Session_pkey" PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "Membership" ("id" TEXT NOT NULL, "organizationId" TEXT NOT NULL, "workspaceId" TEXT NOT NULL, "userId" TEXT NOT NULL, "role" TEXT NOT NULL, "roleIds" TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[], "status" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Membership_pkey" PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "TenantRole" ("id" TEXT NOT NULL, "tenantId" TEXT NOT NULL, "name" TEXT NOT NULL, "permissions" TEXT[] NOT NULL, "resourceScopes" TEXT[] NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "TenantRole_pkey" PRIMARY KEY ("id"));

CREATE TABLE IF NOT EXISTS "TusMerchant" ("id" TEXT NOT NULL, "tenantId" TEXT NOT NULL, "merchantId" TEXT NOT NULL, "cohort" TEXT NOT NULL, "locationId" TEXT NOT NULL, "timezone" TEXT NOT NULL, "staffRoles" TEXT[] NOT NULL, "operatingPolicyVersion" TEXT NOT NULL, "status" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "TusMerchant_pkey" PRIMARY KEY ("id"));
