CREATE TABLE IF NOT EXISTS "TusListing" ("id" TEXT NOT NULL, "contractVersion" TEXT NOT NULL, "tenantId" TEXT NOT NULL, "merchantId" TEXT NOT NULL, "kind" TEXT NOT NULL, "name" TEXT NOT NULL, "description" TEXT NOT NULL, "cohort" TEXT NOT NULL, "locationId" TEXT NOT NULL, "currency" TEXT NOT NULL, "price" BIGINT NOT NULL, "availabilityVersion" INTEGER NOT NULL, "published" BOOLEAN NOT NULL, "policyVersion" TEXT NOT NULL, "stock" INTEGER, "durationMinutes" INTEGER, "capacity" INTEGER, "workingHours" JSONB NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "TusListing_pkey" PRIMARY KEY ("id"));
