CREATE TABLE IF NOT EXISTS "TusCalendar" ("id" TEXT NOT NULL, "tenantId" TEXT NOT NULL, "serviceId" TEXT NOT NULL, "name" TEXT NOT NULL, "timezone" TEXT NOT NULL, "status" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "TusCalendar_pkey" PRIMARY KEY ("id"));
