CREATE TABLE IF NOT EXISTS "TusCommitmentTransition" ("id" TEXT NOT NULL, "tenantId" TEXT NOT NULL, "commitmentId" TEXT NOT NULL, "fromStatus" TEXT NOT NULL, "toStatus" TEXT NOT NULL, "version" INTEGER NOT NULL, "actorId" TEXT NOT NULL, "correlationId" TEXT NOT NULL, "reason" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "TusCommitmentTransition_pkey" PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "TusCommitmentCompensation" ("id" TEXT NOT NULL, "compensationId" TEXT NOT NULL, "tenantId" TEXT NOT NULL, "commitmentId" TEXT NOT NULL, "actorId" TEXT NOT NULL, "correlationId" TEXT NOT NULL, "amount" BIGINT NOT NULL, "currency" TEXT NOT NULL, "reason" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "TusCommitmentCompensation_pkey" PRIMARY KEY ("id"));
