CREATE UNIQUE INDEX IF NOT EXISTS "Membership_workspaceId_userId_key" ON "Membership" ("workspaceId", "userId");
CREATE UNIQUE INDEX IF NOT EXISTS "TenantRole_tenantId_name_key" ON "TenantRole" ("tenantId", "name");
CREATE UNIQUE INDEX IF NOT EXISTS "TusProduct_tenantId_sku_key" ON "TusProduct" ("tenantId", "sku");
CREATE UNIQUE INDEX IF NOT EXISTS "TusService_tenantId_serviceCode_key" ON "TusService" ("tenantId", "serviceCode");
